<script>
(function() {
  /* ==========================================================
     1. WINDOW MANAGEMENT (Drag, Focus, Open, Close)
     ========================================================== */
  let highestZ = 20;

  function bringToFront(win) {
    highestZ += 1;
    win.style.zIndex = highestZ;
  }

  function makeDraggable(win) {
    const header = win.querySelector('.window-header');
    let isDragging = false;
    let startX, startY, initialLeft, initialTop;

    header.addEventListener('mousedown', (e) => {
      if (e.target.classList.contains('win-btn')) return;
      isDragging = true;
      startX = e.clientX;
      startY = e.clientY;
      initialLeft = win.offsetLeft;
      initialTop = win.offsetTop;
      bringToFront(win);
      e.preventDefault();
    });

    window.addEventListener('mousemove', (e) => {
      if (!isDragging) return;
      const dx = e.clientX - startX;
      const dy = e.clientY - startY;
      win.style.left = Math.max(0, initialLeft + dx) + 'px';
      win.style.top = Math.max(0, initialTop + dy) + 'px';
    });

    window.addEventListener('mouseup', () => {
      isDragging = false;
    });

    win.addEventListener('mousedown', () => bringToFront(win));
  }

  const filesWin = document.getElementById('files-window');
  const notepadWin = document.getElementById('notepad-window');
  const openFilesBtn = document.getElementById('open-files');
  const openNotepadBtn = document.getElementById('open-notepad');

  makeDraggable(filesWin);
  makeDraggable(notepadWin);

  function setupWindowControls(win, launcherBtn) {
    const closeBtn = win.querySelector('.win-close');
    closeBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      win.style.display = 'none';
      launcherBtn.classList.remove('running');
    });

    const maxBtn = win.querySelector('.win-max');
    let isMax = false;
    let prevBounds = {};
    maxBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      if (!isMax) {
        prevBounds = {
          left: win.style.left,
          top: win.style.top,
          width: win.style.width,
          height: win.style.height
        };
        win.style.left = '58px';
        win.style.top = '0px';
        win.style.width = 'calc(100vw - 58px)';
        win.style.height = 'calc(100vh - 28px)';
        isMax = true;
      } else {
        win.style.left = prevBounds.left;
        win.style.top = prevBounds.top;
        win.style.width = prevBounds.width;
        win.style.height = prevBounds.height;
        isMax = false;
      }
    });

    const minBtn = win.querySelector('.win-min');
    minBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      win.style.display = 'none';
    });
  }

  setupWindowControls(filesWin, openFilesBtn);
  setupWindowControls(notepadWin, openNotepadBtn);

  openFilesBtn.addEventListener('click', () => {
    filesWin.style.display = 'flex';
    openFilesBtn.classList.add('running');
    bringToFront(filesWin);
  });

  openNotepadBtn.addEventListener('click', () => {
    notepadWin.style.display = 'flex';
    openNotepadBtn.classList.add('running');
    bringToFront(notepadWin);
  });


  /* ==========================================================
     2. FILES APP (Fake Linux Filesystem)
     ========================================================== */
  const fileSystem = {
    "/": {
      type: "dir",
      children: ["bin", "etc", "home", "usr", "var"]
    },
    "/bin": {
      type: "dir",
      children: ["bash", "cat", "grep", "ls", "sh"]
    },
    "/bin/bash": { type: "file" },
    "/bin/cat": { type: "file" },
    "/bin/grep": { type: "file" },
    "/bin/ls": { type: "file" },
    "/bin/sh": { type: "file" },

    "/etc": {
