      children: ["hostname", "hosts", "os-release", "passwd"]
    },
    "/etc/hostname": { type: "file" },
    "/etc/hosts": { type: "file" },
    "/etc/os-release": { type: "file" },
    "/etc/passwd": { type: "file" },

    "/home": {
      type: "dir",
      children: ["user"]
    },
    "/home/user": {
      type: "dir",
      children: ["Documents", "Downloads", "Pictures", "welcome.txt", "notes.md"]
    },
    "/home/user/Documents": {
      type: "dir",
      children: ["resume.pdf", "project-plan.docx", "Work"]
    },
    "/home/user/Documents/resume.pdf": { type: "file" },
    "/home/user/Documents/project-plan.docx": { type: "file" },
    "/home/user/Documents/Work": {
      type: "dir",
      children: ["report.txt"]
    },
    "/home/user/Documents/Work/report.txt": { type: "file" },

    "/home/user/Downloads": {
      type: "dir",
      children: ["ubuntu-24.04-desktop-amd64.iso", "vscode-linux-x64.tar.gz"]
    },
    "/home/user/Downloads/ubuntu-24.04-desktop-amd64.iso": { type: "file" },
    "/home/user/Downloads/vscode-linux-x64.tar.gz": { type: "file" },

    "/home/user/Pictures": {
      type: "dir",
      children: ["wallpaper.jpg", "screenshot.png"]
    },
    "/home/user/Pictures/wallpaper.jpg": { type: "file" },
    "/home/user/Pictures/screenshot.png": { type: "file" },
    "/home/user/welcome.txt": { type: "file" },
    "/home/user/notes.md": { type: "file" },

    "/usr": {
      type: "dir",
      children: ["bin", "lib", "local", "share"]
    },
    "/usr/bin": {
      type: "dir",
      children: ["git", "node", "python3"]
    },
    "/usr/bin/git": { type: "file" },
    "/usr/bin/node": { type: "file" },
    "/usr/bin/python3": { type: "file" },
    "/usr/lib": { type: "dir", children: ["systemd"] },
    "/usr/lib/systemd": { type: "dir", children: [] },
    "/usr/local": { type: "dir", children: ["bin"] },
    "/usr/local/bin": { type: "dir", children: [] },
    "/usr/share": { type: "dir", children: ["icons", "themes"] },
    "/usr/share/icons": { type: "dir", children: [] },
    "/usr/share/themes": { type: "dir", children: [] },

    "/var": {
      type: "dir",
      children: ["cache", "log", "mail", "tmp"]
    },
    "/var/cache": { type: "dir", children: ["apt"] },
    "/var/cache/apt": { type: "dir", children: [] },
    "/var/log": {
      type: "dir",
      children: ["auth.log", "syslog"]
    },
    "/var/log/auth.log": { type: "file" },
    "/var/log/syslog": { type: "file" },
    "/var/mail": { type: "dir", children: [] },
    "/var/tmp": { type: "dir", children: [] }
  };

  let currentPath = "/";
  const filesPathEl = document.getElementById('files-path');
  const filesViewEl = document.getElementById('files-view');
  const filesUpBtn = document.getElementById('files-up');

  function getParentPath(path) {
    if (path === "/") return "/";
    const parts = path.split("/").filter(Boolean);
    parts.pop();
    return parts.length === 0 ? "/" : "/" + parts.join("/");
  }

  function getChildPath(basePath, name) {
    return basePath === "/" ? "/" + name : basePath + "/" + name;
  }

  function renderFiles() {
    filesPathEl.textContent = currentPath;
    filesViewEl.innerHTML = '';

    const dirData = fileSystem[currentPath];
    if (!dirData || dirData.type !== 'dir') return;

    dirData.children.forEach(entryName => {
      const fullPath = getChildPath(currentPath, entryName);
      const isDir = fileSystem[fullPath] && fileSystem[fullPath].type === 'dir';

      const itemEl = document.createElement('div');
      itemEl.className = 'fs-item';

      const iconWrap = document.createElement('div');
      iconWrap.className = 'fs-icon';

      if (isDir) {
        iconWrap.innerHTML = `<svg width="36" height="36" viewBox="0 0 24 24" fill="none">
