  /* ==========================================================
     3. NOTEPAD APP (Tabbed, Persistent)
     ========================================================== */
  const STORAGE_KEY = 'ubuntu_desktop_notepad_tabs_v1';
  const tabsContainer = document.getElementById('tabs');
  const newTabBtn = document.getElementById('new-tab');
  const editor = document.getElementById('editor');

  let notepadState = {
    tabs: [],
    activeId: null,
    nextIndex: 1
  };

  function loadState() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (parsed && Array.isArray(parsed.tabs) && parsed.tabs.length > 0) {
          notepadState = parsed;
          return;
        }
      }
    } catch (err) {
      console.error("Failed to load notepad state from localStorage:", err);
    }

    // Default initial tab
    notepadState = {
      tabs: [
        {
          id: 'tab-1',
          title: 'Untitled 1',
          content: 'Welcome to Ubuntu Text Editor.\nEverything you type here is saved to localStorage!'
        }
      ],
      activeId: 'tab-1',
      nextIndex: 2
    };
    saveState();
  }

  function saveState() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(notepadState));
    } catch (err) {
      console.error("Failed to save notepad state to localStorage:", err);
    }
  }

  function getActiveTab() {
    return notepadState.tabs.find(t => t.id === notepadState.activeId);
  }

  function switchTab(id) {
    // Save current active content before switching
    const currentActive = getActiveTab();
    if (currentActive) {
      currentActive.content = editor.value;
    }

    notepadState.activeId = id;
    const nextActive = getActiveTab();
    if (nextActive) {
      editor.value = nextActive.content || '';
    } else {
      editor.value = '';
    }

    saveState();
    renderTabs();
  }

  function createTab() {
    const currentActive = getActiveTab();
    if (currentActive) {
      currentActive.content = editor.value;
    }

    const tabNum = notepadState.nextIndex || (notepadState.tabs.length + 1);
    notepadState.nextIndex = tabNum + 1;

    const newTabObj = {
      id: 'tab-' + Date.now() + '-' + Math.random().toString(36).substr(2, 5),
      title: 'Untitled ' + tabNum,
      content: ''
    };

    notepadState.tabs.push(newTabObj);
    notepadState.activeId = newTabObj.id;
    editor.value = '';

    saveState();
    renderTabs();
    editor.focus();
  }

  function closeTab(id, e) {
    if (e) e.stopPropagation();

    const idx = notepadState.tabs.findIndex(t => t.id === id);
    if (idx === -1) return;

    notepadState.tabs.splice(idx, 1);

    if (notepadState.tabs.length === 0) {
      // If all tabs closed, create a fresh one
      createTab();
      return;
    }

    if (notepadState.activeId === id) {
      const nextTab = notepadState.tabs[idx] || notepadState.tabs[idx - 1] || notepadState.tabs[0];
      notepadState.activeId = nextTab.id;
      editor.value = nextTab.content || '';
    }

    saveState();
    renderTabs();
  }

  function renderTabs() {
    tabsContainer.innerHTML = '';

    notepadState.tabs.forEach(tab => {
      const tabEl = document.createElement('div');
      tabEl.className = 'tab' + (tab.id === notepadState.activeId ? ' active' : '');

      const nameSpan = document.createElement('span');
      nameSpan.className = 'tab-name';
      nameSpan.textContent = tab.title;

      const closeSpan = document.createElement('span');
      closeSpan.className = 'tab-close-btn';
      closeSpan.textContent = '✕';
      closeSpan.title = 'Close tab';
      closeSpan.addEventListener('click', (e) => closeTab(tab.id, e));

      tabEl.appendChild(nameSpan);
      tabEl.appendChild(closeSpan);

      tabEl.addEventListener('click', () => {
        if (notepadState.activeId !== tab.id) {
          switchTab(tab.id);
        }
      });

      tabsContainer.appendChild(tabEl);
    });
  }

  editor.addEventListener('input', () => {
    const activeTab = getActiveTab();
    if (activeTab) {
